const Fj=[{term:"FIDC",full:"Fundo de Investimento em Direitos Creditórios",category:"Mercado de Capitais",definition:"Fundo que adquire direitos creditórios (recebíveis) de empresas, antecipando recursos por meio da securitização. Permite que organizações transformem seu contas a receber em liquidez imediata, diversificando fontes de financiamento além do crédito bancário tradicional."},{term:"FIP",full:"Fundo de Investimento em Participações",category:"Mercado de Capitais",definition:"Fundo que investe em empresas não listadas em bolsa, adquirindo participação societária para promover reestruturação e valorização. Instrumento central em operações de private equity e estruturas de M&A no Brasil."},{term:"Debêntures de Infraestrutura",full:"Debêntures Incentivadas",category:"Mercado de Capitais",definition:"Títulos de dívida emitidos por empresas de setores prioritários (infraestrutura, logística, energia) com isenção ou redução de Imposto de Renda para os investidores, conforme a Lei nº 12.431/2011. Reduz significativamente o custo efetivo da captação."},{term:"Project Finance",full:"Financiamento de Projeto",category:"Estruturação",definition:"Modalidade de estruturação em que a previsibilidade de caixa do próprio projeto serve como garantia principal, isolando os riscos do balanço dos acionistas (non-recourse ou limited recourse). Exige a constituição de uma SPE e alocação eficiente de riscos entre as partes."},{term:"Valuation",full:"Avaliação de Empresas",category:"M&A",definition:"Processo de determinação do valor justo de um negócio, utilizando metodologias como o Fluxo de Caixa Descontado (FCD) e a análise de múltiplos de mercado. Fundamenta decisões de fusões, aquisições e reestruturações societárias conforme o CPC 46."},{term:"SPE",full:"Sociedade de Propósito Específico",category:"Estruturação",definition:"Entidade jurídica criada exclusivamente para isolar e gerir um projeto específico, separando seus riscos e fluxos do balanço patrimonial dos investidores. Essencial em estruturas de Project Finance e parcerias público-privadas."},{term:"PPP",full:"Parceria Público-Privada",category:"Estruturação",definition:"Arranjo contratual previsto na Lei nº 11.079/2004 em que a administração pública contrata a prestação de serviços com o setor privado, envolvendo obras e/ou serviços, com reparte de riscos e remuneração vinculada ao desempenho."},{term:"PPA",full:"Plano Plurianual",category:"Orçamento Público",definition:"Instrumento de planejamento de médio prazo (quatro anos) que define as diretrizes, objetivos e metas da administração pública federal, orientando as leis orçamentárias anuais."},{term:"LDO",full:"Lei de Diretrizes Orçamentárias",category:"Orçamento Público",definition:"Lei anual que estabelece as metas e prioridades da administração pública para o ano seguinte, orienta a elaboração da LOA e dispõe sobre alterações na legislação tributária e de políticas de aplicação das agências financeiras."},{term:"LOA",full:"Lei Orçamentária Anual",category:"Orçamento Público",definition:"Lei que estima as receitas e fixa as despesas do Poder Público para cada exercício financeiro. É o instrumento de execução do orçamento-programa, devendo estar harmonizada com o PPA e a LDO."},{term:"SUDENE",full:"Superintendência do Desenvolvimento do Nordeste",category:"Incentivos Fiscais",definition:"Órgão que opera incentivos fiscais regionais para a região Nordeste, permitindo redução de Imposto de Renda para empresas instaladas na área de atuação, condicionada à aprovação de projetos de investimento produtivo."},{term:"PRODEPE",full:"Programa de Desenvolvimento do Estado de Pernambuco",category:"Incentivos Fiscais",definition:"Programa estadual de incentivo fiscal que concede crédito presumido de ICMS para empresas que investem no estado de Pernambuco, estimulando a expansão industrial e a geração de emprego."},{term:"BNDES",full:"Banco Nacional de Desenvolvimento Econômico e Social",category:"Fomento",definition:"Principal instrumento do governo federal para financiamento de longo prazo no país. Financia projetos de infraestrutura, inovação, expansão industrial e exportação com taxas e prazos diferenciados do mercado."},{term:"BNB",full:"Banco do Nordeste do Brasil",category:"Fomento",definition:"Instituição financeira regional que opera linhas de fomento para a região Nordeste, incluindo o Fundo Constitucional de Financiamento do Nordeste (FNE), com foco em desenvolvimento regional sustentável."},{term:"BASA",full:"Banco da Amazônia",category:"Fomento",definition:"Banco de desenvolvimento que opera o Fundo Constitucional de Financiamento do Norte (FNO), financiando projetos produtivos na região Amazônica com condições especiais de crédito."},{term:"FINEP",full:"Financiadora de Estudos e Projetos",category:"Fomento",definition:"Empresa pública vinculada ao Ministério de Ciência, Tecnologia e Inovação que financia pesquisa, desenvolvimento e inovação no país, por meio de recursos reembolsáveis e não reembolsáveis (subvenção econômica)."},{term:"Off-take",full:"Contrato de Compra e Venda Futura",category:"Estruturação",definition:"Contrato que assegura a compra da produção ou serviço futuro de um projeto, garantindo previsibilidade de receita. Fundamental para viabilizar o Project Finance, pois dá aos financiadores confiança na geração de caixa."},{term:"Non-recourse",full:"Financiamento Sem Recurso",category:"Estruturação",definition:"Modalidade em que os financiadores têm como garantia apenas os ativos e fluxos de caixa do próprio projeto, sem acesso ao patrimônio dos acionistas. Maximiza o isolamento de riscos em estruturas de Project Finance."},{term:"Earn-out",full:"Cláusula de Remuneração Adicional",category:"M&A",definition:"Mecanismo em operações de M&A em que parte do preço é paga condicionalmente ao atingimento de metas de desempenho pós-fechamento, protegendo o comprador contra incertezas e alinhando incentivos."},{term:"Due Diligence",full:"Diligência Devida",category:"M&A",definition:"Investigação minuciosa de uma empresa-alvo em processos de fusão ou aquisição, identificando passivos ocultos, contingências tributárias e trabalhistas que possam impactar o preço final da transação."},{term:"Covenants",full:"Cláusulas Restritivas",category:"Mercado de Capitais",definition:"Obrigações contratuais em contratos de dívida que limitam ações do devedor (ex.: índices de endividamento). O descumprimento pode acarretar vencimento antecipado e comprometimento severo da liquidez."},{term:"Subvenção Econômica",full:"Subvenção Não Reembolsável",category:"Inovação",definition:"Repasse de recursos públicos não reembolsáveis a empresas que invadem em P&D, previsto na Lei da Inovação. Financia o risco tecnológico, exigindo prestação de contas rigorosa e separação de gastos."},{term:"Princípios do Equador",full:"Equator Principles",category:"Estruturação",definition:"Marco voluntário adotado por instituições financeiras globais para gestão de riscos socioambientais em projetos. O atendimento amplia o acesso a fontes de financiamento externas e exige conformidade ambiental e social."},{term:"Rating de Crédito",full:"Classificação de Risco",category:"Mercado de Capitais",definition:"Avaliação da capacidade de pagamento de um emissor de dívida, realizada por agências especializadas. Determina o custo e a viabilidade de emissões públicas de debêntures e outros instrumentos no mercado de capitais."}];
